{
  "application": "report-generation",
  "case_id": "case-ev-charging-grid-optimization-en",
  "language": "en",
  "report": {
    "type": "analytics-report",
    "audience": "management",
    "tone": "analytical, data-forward, actionable"
  },
  "brief": {
    "title": "EV Charging Network Performance & Grid Optimization Analytics Report",
    "one_liner": "A comprehensive analysis of EV charging station operations, demand patterns, grid load dynamics, and optimization opportunities across a smart-grid charging network.",
    "goal": "Equip infrastructure managers and grid planners with data-driven insights into station utilization, queue bottlenecks, renewable energy integration, pricing impacts, and actionable recommendations to improve charging throughput, reduce wait times, and optimize grid load balancing."
  },
  "required_sections": [
    {
      "section_id": "station-utilization",
      "title": "Station Utilization & Demand Analysis",
      "objective": "Analyze charging demand distribution across stations and location types (Urban, Highway, Suburban), identifying high-demand stations, peak utilization periods, and capacity constraints."
    },
    {
      "section_id": "queue-wait-analysis",
      "title": "Queue Length & Waiting Time Analysis",
      "objective": "Examine queue lengths and waiting times by station, time slot, vehicle type, and traffic density to identify bottleneck patterns and quantify the customer experience impact."
    },
    {
      "section_id": "energy-grid-load",
      "title": "Energy Consumption & Grid Load Patterns",
      "objective": "Assess energy consumption patterns, station load profiles across time slots and days of the week, and the relationship between charging power levels and grid stress."
    },
    {
      "section_id": "renewable-pricing",
      "title": "Renewable Energy Integration & Dynamic Pricing",
      "objective": "Evaluate the renewable energy ratio across different conditions (time, weather, location) and analyze how dynamic electricity pricing correlates with demand, renewable availability, and optimization rewards."
    },
    {
      "section_id": "vehicle-charging-behavior",
      "title": "Vehicle Charging Behavior & Session Profiles",
      "objective": "Profile charging sessions by vehicle type, examining battery capacity, initial/final SOC, energy consumed, charging duration, and priority distribution to understand fleet composition and usage patterns."
    },
    {
      "section_id": "optimization-recommendations",
      "title": "Optimization Insights & Recommendations",
      "objective": "Synthesize findings into actionable recommendations for load balancing, queue management, pricing strategy adjustments, and renewable energy maximization, leveraging the optimization reward metric as a performance signal."
    }
  ],
  "kpis": [
    {
      "name": "Average Waiting Time",
      "description": "Mean time (in minutes) vehicles spend in queue before charging begins, segmented by time slot and location type."
    },
    {
      "name": "Average Energy Consumed per Session",
      "description": "Mean energy transferred (kWh) per charging session, indicating typical session intensity."
    },
    {
      "name": "Mean Station Load",
      "description": "Average electrical load on station local grids, as an indicator of grid stress levels."
    },
    {
      "name": "Renewable Energy Ratio",
      "description": "Average proportion of grid energy sourced from renewables, measuring sustainability performance."
    },
    {
      "name": "Mean Optimization Reward",
      "description": "Average synthetic reward metric across sessions, serving as a composite indicator of grid optimization effectiveness."
    }
  ],
  "analysis_dimensions": [
    "location_type",
    "vehicle_type",
    "time_slot",
    "day_of_week",
    "weather_condition"
  ]
}

